import React, { useState, useEffect } from 'react';
import Login from './pages/Login';
import Signup from './pages/Signup';
import Dashboard from './pages/Dashboard';
import { readAuth, saveAuth, clearAuth } from './utils/auth';

function App(){ 
  const [auth, setAuth] = useState(readAuth()); 
  const [view, setView] = useState(auth ? 'dashboard' : 'login'); 

  useEffect(()=> { saveAuth(auth); }, [auth]); 

  const logout = () => { clearAuth(); setAuth(null); setView('login'); }; 

  const backgroundClass = 'bg-app'; 
return (
    // Increased maxWidth to make the input boxes wider
    <div className="form-container" style={{ maxWidth: 500 }}>
      <h3>Login</h3>
      {err && <div style={{ color: 'red' }}>{err}</div>}
      <form onSubmit={submit}>
        <div>
          <label>Email</label><br />
          <input value={email} onChange={e=>setEmail(e.target.value)} />
        </div>
        <div>
          <label>Password</label><br />
          <input type="password" value={password} onChange={e=>setPassword(e.target.value)} />
        </div>
        <button type="submit">Login</button>
      </form>
      <p>Don't have an account? <button className="switch-btn" onClick={onSwitch}>Sign up</button></p>
    </div>
  );
}
